export const LIMITS={hours:[.25,1000],people:[1,50],rate:[.01,10000],travelTime:[0,100],materials:[0,1000000],travel:[0,1000000],other:[0,1000000],monthly:[0,1000000],billable:[1,10000],margin:[0,90],contingency:[0,100],adjustment:[-50,100],minimum:[0,1000000],round:[1,100],tax:[0,30],deposit:[0,100]};
export function validate(v){const errors={};for(const [k,[min,max]] of Object.entries(LIMITS)){const n=Number(v[k]);if(v[k]===''||v[k]===null||!Number.isFinite(n)||n<min||n>max)errors[k]=`Enter a number from ${min} to ${max}.`; }if(!Number.isInteger(Number(v.people)))errors.people='Enter a whole number of people.';if(![1,5,10,25,50,100].includes(Number(v.round)))errors.round='Choose a rounding option.';if(!String(v.job||'').trim())errors.job='Give this job a name.';return errors;}
export function calculate(v){const errors=validate(v);if(Object.keys(errors).length)return{errors};const n=Object.fromEntries(Object.keys(LIMITS).map(k=>[k,Number(v[k])]));const crewHours=(n.hours+n.travelTime)*n.people;const labor=crewHours*n.rate;const overheadRate=n.monthly/n.billable;const overhead=crewHours*overheadRate;const direct=labor+n.materials+n.travel+n.other;const subtotal=direct+overhead;const buffer=subtotal*n.contingency/100;const cost=subtotal+buffer;const target=cost/(1-n.margin/100);const adjustment=target*n.adjustment/100;const adjusted=target+adjustment;const price=Math.ceil(Math.max(adjusted,n.minimum)/n.round)*n.round;const profit=price-cost;const effectiveMargin=price>0?profit/price*100:0;const taxAmount=Math.round(price*n.tax)/100;const total=Math.round((price+taxAmount)*100)/100;const depositAmount=Math.round(total*n.deposit)/100;const balance=Math.round((total-depositAmount)*100)/100;return{errors:{},crewHours,labor,overheadRate,overhead,direct,subtotal,buffer,cost,target,adjustment,adjusted,price,profit,effectiveMargin,taxAmount,total,depositAmount,balance,minimumApplied:n.minimum>adjusted,belowCost:price<cost,belowTarget:effectiveMargin+0.001<n.margin};}
